"use strict";(self.webpackChunkpgdoc_02=self.webpackChunkpgdoc_02||[]).push([[55763],{7371:(n,e,t)=>{t.r(e),t.d(e,{assets:()=>c,contentTitle:()=>o,default:()=>d,frontMatter:()=>a,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"IV. Client Interfaces/libpq \u2014 C Library/libpq-example","title":"34.22. Example Programs","description":"Supported versions: 13 / 14 / 15 / 16 / 17","source":"@site/docs/IV. Client Interfaces/34. libpq \u2014 C Library/libpq-example.md","sourceDirName":"IV. Client Interfaces/34. libpq \u2014 C Library","slug":"/IV. Client Interfaces/libpq \u2014 C Library/libpq-example","permalink":"/demo_docu/IV. Client Interfaces/libpq \u2014 C Library/libpq-example","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"34.22. Example Programs"},"sidebar":"autoGeneratedSidebar","previous":{"title":"34.14. Event System","permalink":"/demo_docu/IV. Client Interfaces/libpq \u2014 C Library/libpq-events"},"next":{"title":"34.3. Command Execution Functions","permalink":"/demo_docu/IV. Client Interfaces/libpq \u2014 C Library/libpq-exec"}}');var s=t(74848),i=t(28453);const a={title:"34.22. Example Programs"},o=void 0,c={},l=[];function p(n){const e={code:"code",hr:"hr",p:"p",pre:"pre",strong:"strong",...(0,i.R)(),...n.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(e.p,{children:"Supported versions: 13 / 14 / 15 / 16 / 17"}),"\n",(0,s.jsx)(e.p,{children:"Development versions: 18 / devel"}),"\n",(0,s.jsx)(e.p,{children:"Unsupported versions: 10 / 11 / 12 / 7.1 / 7.2 / 7.3 / 7.4 / 8.0 / 8.1 / 8.2 / 8.3 / 8.4 / 9.0 / 9.1 / 9.2 / 9.3 / 9.4 / 9.5 / 9.6"}),"\n",(0,s.jsx)(e.hr,{}),"\n",(0,s.jsxs)(e.p,{children:["These examples and others can be found in the directory ",(0,s.jsx)(e.code,{children:"src/test/examples"})," in the source code distribution."]}),"\n",(0,s.jsx)(e.p,{children:(0,s.jsx)(e.strong,{children:"Example  34.1. libpq Example Program 1"})}),"\n",(0,s.jsx)(e.pre,{children:(0,s.jsx)(e.code,{children:'/*\n * src/test/examples/testlibpq.c\n *\n *\n * testlibpq.c\n *\n *      Test the C version of libpq, the PostgreSQL frontend library.\n */\n#include <stdio.h>\n#include <stdlib.h>\n#include "libpq-fe.h"\n\nstatic void\nexit_nicely(PGconn *conn)\n{\n    PQfinish(conn);\n    exit(1);\n}\n\nint\nmain(int argc, char **argv)\n{\n    const char *conninfo;\n    PGconn     *conn;\n    PGresult   *res;\n    int         nFields;\n    int         i,\n                j;\n\n    /*\n     * If the user supplies a parameter on the command line, use it as the\n     * conninfo string; otherwise default to setting dbname=postgres and using\n     * environment variables or defaults for all other connection parameters.\n     */\n    if (argc > 1)\n        conninfo = argv[1];\n    else\n        conninfo = "dbname = postgres";\n\n    /* Make a connection to the database */\n    conn = PQconnectdb(conninfo);\n\n    /* Check to see that the backend connection was successfully made */\n    if (PQstatus(conn) != CONNECTION_OK)\n    {\n        fprintf(stderr, "%s", PQerrorMessage(conn));\n        exit_nicely(conn);\n    }\n\n    /* Set always-secure search path, so malicious users can\'t take control. */\n    res = PQexec(conn,\n                 "SELECT pg_catalog.set_config(\'search_path\', \'\', false)");\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SET failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    /*\n     * Should PQclear PGresult whenever it is no longer needed to avoid memory\n     * leaks\n     */\n    PQclear(res);\n\n    /*\n     * Our test case here involves using a cursor, for which we must be inside\n     * a transaction block.  We could do the whole thing with a single\n     * PQexec() of "select * from pg_database", but that\'s too trivial to make\n     * a good example.\n     */\n\n    /* Start a transaction block */\n    res = PQexec(conn, "BEGIN");\n    if (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "BEGIN command failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    /*\n     * Fetch rows from pg_database, the system catalog of databases\n     */\n    res = PQexec(conn, "DECLARE myportal CURSOR FOR select * from pg_database");\n    if (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "DECLARE CURSOR failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    res = PQexec(conn, "FETCH ALL in myportal");\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "FETCH ALL failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    /* first, print out the attribute names */\n    nFields = PQnfields(res);\n    for (i = 0; i < nFields; i++)\n        printf("%-15s", PQfname(res, i));\n    printf("\\n\\n");\n\n    /* next, print out the rows */\n    for (i = 0; i < PQntuples(res); i++)\n    {\n        for (j = 0; j < nFields; j++)\n            printf("%-15s", PQgetvalue(res, i, j));\n        printf("\\n");\n    }\n\n    PQclear(res);\n\n    /* close the portal ... we don\'t bother to check for errors ... */\n    res = PQexec(conn, "CLOSE myportal");\n    PQclear(res);\n\n    /* end the transaction */\n    res = PQexec(conn, "END");\n    PQclear(res);\n\n    /* close the connection to the database and cleanup */\n    PQfinish(conn);\n\n    return 0;\n}\n\n'})}),"\n",(0,s.jsx)(e.p,{children:(0,s.jsx)(e.strong,{children:"Example  34.2. libpq Example Program 2"})}),"\n",(0,s.jsx)(e.pre,{children:(0,s.jsx)(e.code,{children:'/*\n * src/test/examples/testlibpq2.c\n *\n *\n * testlibpq2.c\n *      Test of the asynchronous notification interface\n *\n * Start this program, then from psql in another window do\n *   NOTIFY TBL2;\n * Repeat four times to get this program to exit.\n *\n * Or, if you want to get fancy, try this:\n * populate a database with the following commands\n * (provided in src/test/examples/testlibpq2.sql):\n *\n *   CREATE SCHEMA TESTLIBPQ2;\n *   SET search_path = TESTLIBPQ2;\n *   CREATE TABLE TBL1 (i int4);\n *   CREATE TABLE TBL2 (i int4);\n *   CREATE RULE r1 AS ON INSERT TO TBL1 DO\n *     (INSERT INTO TBL2 VALUES (new.i); NOTIFY TBL2);\n *\n * Start this program, then from psql do this four times:\n *\n *   INSERT INTO TESTLIBPQ2.TBL1 VALUES (10);\n */\n\n#ifdef WIN32\n#include <windows.h>\n#endif\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <errno.h>\n#include <sys/select.h>\n#include <sys/time.h>\n#include <sys/types.h>\n\n#include "libpq-fe.h"\n\nstatic void\nexit_nicely(PGconn *conn)\n{\n    PQfinish(conn);\n    exit(1);\n}\n\nint\nmain(int argc, char **argv)\n{\n    const char *conninfo;\n    PGconn     *conn;\n    PGresult   *res;\n    PGnotify   *notify;\n    int         nnotifies;\n\n    /*\n     * If the user supplies a parameter on the command line, use it as the\n     * conninfo string; otherwise default to setting dbname=postgres and using\n     * environment variables or defaults for all other connection parameters.\n     */\n    if (argc > 1)\n        conninfo = argv[1];\n    else\n        conninfo = "dbname = postgres";\n\n    /* Make a connection to the database */\n    conn = PQconnectdb(conninfo);\n\n    /* Check to see that the backend connection was successfully made */\n    if (PQstatus(conn) != CONNECTION_OK)\n    {\n        fprintf(stderr, "%s", PQerrorMessage(conn));\n        exit_nicely(conn);\n    }\n\n    /* Set always-secure search path, so malicious users can\'t take control. */\n    res = PQexec(conn,\n                 "SELECT pg_catalog.set_config(\'search_path\', \'\', false)");\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SET failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    /*\n     * Should PQclear PGresult whenever it is no longer needed to avoid memory\n     * leaks\n     */\n    PQclear(res);\n\n    /*\n     * Issue LISTEN command to enable notifications from the rule\'s NOTIFY.\n     */\n    res = PQexec(conn, "LISTEN TBL2");\n    if (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "LISTEN command failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    /* Quit after four notifies are received. */\n    nnotifies = 0;\n    while (nnotifies < 4)\n    {\n        /*\n         * Sleep until something happens on the connection.  We use select(2)\n         * to wait for input, but you could also use poll() or similar\n         * facilities.\n         */\n        int         sock;\n        fd_set      input_mask;\n\n        sock = PQsocket(conn);\n\n        if (sock < 0)\n            break;              /* shouldn\'t happen */\n\n        FD_ZERO(&input_mask);\n        FD_SET(sock, &input_mask);\n\n        if (select(sock + 1, &input_mask, NULL, NULL, NULL) < 0)\n        {\n            fprintf(stderr, "select() failed: %s\\n", strerror(errno));\n            exit_nicely(conn);\n        }\n\n        /* Now check for input */\n        PQconsumeInput(conn);\n        while ((notify = PQnotifies(conn)) != NULL)\n        {\n            fprintf(stderr,\n                    "ASYNC NOTIFY of \'%s\' received from backend PID %d\\n",\n                    notify->relname, notify->be_pid);\n            PQfreemem(notify);\n            nnotifies++;\n            PQconsumeInput(conn);\n        }\n    }\n\n    fprintf(stderr, "Done.\\n");\n\n    /* close the connection to the database and cleanup */\n    PQfinish(conn);\n\n    return 0;\n}\n\n'})}),"\n",(0,s.jsx)(e.p,{children:(0,s.jsx)(e.strong,{children:"Example  34.3. libpq Example Program 3"})}),"\n",(0,s.jsx)(e.pre,{children:(0,s.jsx)(e.code,{children:'/*\n * src/test/examples/testlibpq3.c\n *\n *\n * testlibpq3.c\n *      Test out-of-line parameters and binary I/O.\n *\n * Before running this, populate a database with the following commands\n * (provided in src/test/examples/testlibpq3.sql):\n *\n * CREATE SCHEMA testlibpq3;\n * SET search_path = testlibpq3;\n * SET standard_conforming_strings = ON;\n * CREATE TABLE test1 (i int4, t text, b bytea);\n * INSERT INTO test1 values (1, \'joe\'\'s place\', \'\\000\\001\\002\\003\\004\');\n * INSERT INTO test1 values (2, \'ho there\', \'\\004\\003\\002\\001\\000\');\n *\n * The expected output is:\n *\n * tuple 0: got\n *  i = (4 bytes) 1\n *  t = (11 bytes) \'joe\'s place\'\n *  b = (5 bytes) \\000\\001\\002\\003\\004\n *\n * tuple 0: got\n *  i = (4 bytes) 2\n *  t = (8 bytes) \'ho there\'\n *  b = (5 bytes) \\004\\003\\002\\001\\000\n */\n\n#ifdef WIN32\n#include <windows.h>\n#endif\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <stdint.h>\n#include <string.h>\n#include <sys/types.h>\n#include "libpq-fe.h"\n\n/* for ntohl/htonl */\n#include <netinet/in.h>\n#include <arpa/inet.h>\n\n\nstatic void\nexit_nicely(PGconn *conn)\n{\n    PQfinish(conn);\n    exit(1);\n}\n\n/*\n * This function prints a query result that is a binary-format fetch from\n * a table defined as in the comment above.  We split it out because the\n * main() function uses it twice.\n */\nstatic void\nshow_binary_results(PGresult *res)\n{\n    int         i,\n                j;\n    int         i_fnum,\n                t_fnum,\n                b_fnum;\n\n    /* Use PQfnumber to avoid assumptions about field order in result */\n    i_fnum = PQfnumber(res, "i");\n    t_fnum = PQfnumber(res, "t");\n    b_fnum = PQfnumber(res, "b");\n\n    for (i = 0; i < PQntuples(res); i++)\n    {\n        char       *iptr;\n        char       *tptr;\n        char       *bptr;\n        int         blen;\n        int         ival;\n\n        /* Get the field values (we ignore possibility they are null!) */\n        iptr = PQgetvalue(res, i, i_fnum);\n        tptr = PQgetvalue(res, i, t_fnum);\n        bptr = PQgetvalue(res, i, b_fnum);\n\n        /*\n         * The binary representation of INT4 is in network byte order, which\n         * we\'d better coerce to the local byte order.\n         */\n        ival = ntohl(*((uint32_t *) iptr));\n\n        /*\n         * The binary representation of TEXT is, well, text, and since libpq\n         * was nice enough to append a zero byte to it, it\'ll work just fine\n         * as a C string.\n         *\n         * The binary representation of BYTEA is a bunch of bytes, which could\n         * include embedded nulls so we have to pay attention to field length.\n         */\n        blen = PQgetlength(res, i, b_fnum);\n\n        printf("tuple %d: got\\n", i);\n        printf(" i = (%d bytes) %d\\n",\n               PQgetlength(res, i, i_fnum), ival);\n        printf(" t = (%d bytes) \'%s\'\\n",\n               PQgetlength(res, i, t_fnum), tptr);\n        printf(" b = (%d bytes) ", blen);\n        for (j = 0; j < blen; j++)\n            printf("\\\\%03o", bptr[j]);\n        printf("\\n\\n");\n    }\n}\n\nint\nmain(int argc, char **argv)\n{\n    const char *conninfo;\n    PGconn     *conn;\n    PGresult   *res;\n    const char *paramValues[1];\n    int         paramLengths[1];\n    int         paramFormats[1];\n    uint32_t    binaryIntVal;\n\n    /*\n     * If the user supplies a parameter on the command line, use it as the\n     * conninfo string; otherwise default to setting dbname=postgres and using\n     * environment variables or defaults for all other connection parameters.\n     */\n    if (argc > 1)\n        conninfo = argv[1];\n    else\n        conninfo = "dbname = postgres";\n\n    /* Make a connection to the database */\n    conn = PQconnectdb(conninfo);\n\n    /* Check to see that the backend connection was successfully made */\n    if (PQstatus(conn) != CONNECTION_OK)\n    {\n        fprintf(stderr, "%s", PQerrorMessage(conn));\n        exit_nicely(conn);\n    }\n\n    /* Set always-secure search path, so malicious users can\'t take control. */\n    res = PQexec(conn, "SET search_path = testlibpq3");\n    if (PQresultStatus(res) != PGRES_COMMAND_OK)\n    {\n        fprintf(stderr, "SET failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n    PQclear(res);\n\n    /*\n     * The point of this program is to illustrate use of PQexecParams() with\n     * out-of-line parameters, as well as binary transmission of data.\n     *\n     * This first example transmits the parameters as text, but receives the\n     * results in binary format.  By using out-of-line parameters we can avoid\n     * a lot of tedious mucking about with quoting and escaping, even though\n     * the data is text.  Notice how we don\'t have to do anything special with\n     * the quote mark in the parameter value.\n     */\n\n    /* Here is our out-of-line parameter value */\n    paramValues[0] = "joe\'s place";\n\n    res = PQexecParams(conn,\n                       "SELECT * FROM test1 WHERE t = $1",\n                       1,       /* one param */\n                       NULL,    /* let the backend deduce param type */\n                       paramValues,\n                       NULL,    /* don\'t need param lengths since text */\n                       NULL,    /* default to all text params */\n                       1);      /* ask for binary results */\n\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SELECT failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    show_binary_results(res);\n\n    PQclear(res);\n\n    /*\n     * In this second example we transmit an integer parameter in binary form,\n     * and again retrieve the results in binary form.\n     *\n     * Although we tell PQexecParams we are letting the backend deduce\n     * parameter type, we really force the decision by casting the parameter\n     * symbol in the query text.  This is a good safety measure when sending\n     * binary parameters.\n     */\n\n    /* Convert integer value "2" to network byte order */\n    binaryIntVal = htonl((uint32_t) 2);\n\n    /* Set up parameter arrays for PQexecParams */\n    paramValues[0] = (char *) &binaryIntVal;\n    paramLengths[0] = sizeof(binaryIntVal);\n    paramFormats[0] = 1;        /* binary */\n\n    res = PQexecParams(conn,\n                       "SELECT * FROM test1 WHERE i = $1::int4",\n                       1,       /* one param */\n                       NULL,    /* let the backend deduce param type */\n                       paramValues,\n                       paramLengths,\n                       paramFormats,\n                       1);      /* ask for binary results */\n\n    if (PQresultStatus(res) != PGRES_TUPLES_OK)\n    {\n        fprintf(stderr, "SELECT failed: %s", PQerrorMessage(conn));\n        PQclear(res);\n        exit_nicely(conn);\n    }\n\n    show_binary_results(res);\n\n    PQclear(res);\n\n    /* close the connection to the database and cleanup */\n    PQfinish(conn);\n\n    return 0;\n}\n\n'})})]})}function d(n={}){const{wrapper:e}={...(0,i.R)(),...n.components};return e?(0,s.jsx)(e,{...n,children:(0,s.jsx)(p,{...n})}):p(n)}},28453:(n,e,t)=>{t.d(e,{R:()=>a,x:()=>o});var r=t(96540);const s={},i=r.createContext(s);function a(n){const e=r.useContext(i);return r.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function o(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(s):n.components||s:a(n.components),r.createElement(i.Provider,{value:e},n.children)}}}]);